'use strict';
const $=s=>document.querySelector(s);
function catalogLabel(type){
 const def=ComponentRegistry.get(type);
 return def?.label||def?.name||'Component';
}
function batteryInfo(n){
 const variants=ComponentRegistry.variants('battery');
 return variants.find(pack=>pack.id===n.pack)||variants.find(pack=>pack.id==='eneloop4')||variants[0]||{name:'Battery pack'};
}
const componentLabel=n=>n.type==='battery'?batteryInfo(n).name:catalogLabel(n.type);
let state={name:'Untitled project',nodes:[],wires:[]}, pendingRestore=null, selected=null, pending=null, running=false, started=false, elapsed=0, last=0, pan={x:0,y:0}, zoom=1, history=[];
const viewport=$('#viewport'),world=$('#world');
const uid=()=>globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isController=n=>n.type==='mcu'||n.type==='board'||n.type==='esp8266';
const boardFor=n=>RobotModel.board(state,n);
const nodeName=n=>n.type==='board'?boardFor(n).name:catalogLabel(n.type);
const pinName=(n,p)=>RobotModel.pins(state,n)[p]?.name||'Pin';
function valid(s){return RobotModel.valid(s)}
function migrateProject(s){if(!s||!Array.isArray(s.nodes))return s;for(const n of s.nodes){if(n?.type!=='esp8266'||!Array.isArray(n.modes))continue;const oldCount=n.modes.length;if(oldCount<RobotModel.espPins.length)n.modes=[...n.modes,...Array(RobotModel.espPins.length-oldCount).fill('low')];if(Array.isArray(n.pinDirections)&&n.pinDirections.length<RobotModel.espPins.length){const old=n.pinDirections;n.pinDirections=RobotModel.espPins.map((p,i)=>i<old.length?(old[i]||p.kind):p.kind)}}return s}
try{const s=migrateProject(JSON.parse(localStorage.getItem('robot-canvas-v1')));if(valid(s))state=s;else if(s?.nodes?.some?.(n=>n&&typeof n.type==='string'&&!ComponentRegistry.get(n.type)))pendingRestore=s}catch{}
state.boards??=[];
function save(){if(pendingRestore){$('#saved').textContent='Waiting for saved project parts';return}try{localStorage.setItem('robot-canvas-v1',JSON.stringify(state));$('#saved').textContent='Saved locally'}catch{$('#saved').textContent='Not saved — export your project';toast('Browser storage is full or unavailable. Export your project to keep changes.')}}
function snapshot(){history.push(JSON.stringify(state));if(history.length>40)history.shift()}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function signal(n,p){return RobotModel.output(state,n,p,started,elapsed,window.Firmware?.read)}
function input(n,p=0){return RobotModel.input(state,n,p,started,elapsed,window.Firmware?.read)}
function boardHTML(n){const b=boardFor(n);return `<div class="node board ${n.id===selected?'selected':''}" data-id="${n.id}" style="left:${n.x}px;top:${n.y}px;width:280px"><div class="node-header">${esc(b.name)}<span class="node-label">CUSTOM</span></div><div class="board-face" style="aspect-ratio:${b.width}/${b.height}"><img src="${b.image}" alt="${esc(b.name)}" draggable="false">${b.pins.map((p,i)=>`<button class="pin board-pin ${p.kind} ${pending?.id===n.id&&Number(pending.pin)===i?'pending':''}" data-pin="${i}" style="left:${p.x*100}%;top:${p.y*100}%" aria-label="Connect ${esc(p.name)} (${p.kind})" title="${esc(p.name)} · ${p.kind}"><span>${esc(p.name)}</span></button>`).join('')}</div></div>`}
function genericPeripheralHTML(n,def){const visual=def.visual||{},pins=RobotModel.pins(state,n);const art=visual.assetUrl?`<img class="generic-image" src="${esc(visual.assetUrl)}" alt="${esc(visual.alt||def.name)}" draggable="false">`:`<span class="generic-symbol">${esc(visual.symbol||def.icon||'▦')}</span>`;return `<div class="node-body generic-art ${esc(visual.className||'')}">${art}</div>${pins.map((p,i)=>`<div class="pin-row generic-pin-row"><button class="pin ${RobotModel.sourceKind(p.kind)?'':'input'} ${p.kind==='reserved'?'reserved':''}" data-pin="${i}" ${p.kind==='reserved'?'disabled':''} aria-label="Connect ${esc(p.name)} (${esc(p.kind)})" title="${esc(p.name)} · ${esc(p.kind)}"></button><span>${esc(p.name)}</span><small>${esc(p.kind)}</small></div>`).join('')}`}
function peripheralHTML(n){const definition=ComponentRegistry.get(n.type);if(definition?.renderer==='generic')return genericPeripheralHTML(n,definition);if(n.type==='motorDriver')return `<div class="driver-caption">DUAL H-BRIDGE · 2 MOTORS</div>${RobotModel.pins(state,n).map((p,i)=>`<div class="pin-row driver-pin-row"><button class="pin ${p.kind==='input'?'input':''}" data-pin="${i}" aria-label="${p.name} (${p.kind})" title="${p.name} · ${p.kind}"></button><span>${p.name}</span><small>${p.kind==='input'?'CONTROL':p.kind==='output'?'MOTOR OUT':p.kind==='power-input'?'SUPPLY':'GROUND'}</small></div>`).join('')}`;if(n.type==='ultrasonic')return `<div class="node-body sonar-art"><span>◉</span><span>◉</span></div>${RobotModel.pins(state,n).map((p,i)=>`<div class="pin-row component-pin-row"><button class="pin ${p.kind==='input'?'input':''}" data-pin="${i}" aria-label="${p.name}"></button><span>${p.name}</span><span></span></div>`).join('')}`;if(n.type==='battery'){const pack=batteryInfo(n);return `<div class="node-body"><span class="battery-art ${n.pack==='nineVolt'?'battery-9v':''}"><i></i><b>${pack.cells}</b></span></div><div class="pin-row battery-pin-row"><span>${pack.positive||'V+ · POSITIVE'}</span><button class="pin" data-pin="0" aria-label="Battery positive power output"></button></div><div class="pin-row battery-pin-row"><span>${pack.negative||'GND · NEGATIVE'}</span><button class="pin" data-pin="1" aria-label="Battery ground output"></button></div><small class="battery-rating">${pack.voltage} · ${pack.capacity}</small>`}const body=n.type==='led'?'<span class="light"></span>':n.type==='motor'?'<span class="rotor">✣</span>':'<span class="arm"></span>';let rows='';if(n.type==='servo')rows='<div class="pin-row servo-pin-row"><button class="pin input" data-pin="0" aria-label="Connect servo signal (orange)"></button><span>SIGNAL <small>ORANGE</small></span><span class="output-state">0°</span></div><div class="pin-row servo-pin-row"><button class="pin input" data-pin="1" aria-label="Connect servo power (red)"></button><span>V+ <small>RED</small></span><span></span></div><div class="pin-row servo-pin-row"><button class="pin input" data-pin="2" aria-label="Connect servo ground (brown or black)"></button><span>GND <small>BROWN / BLACK</small></span><span></span></div>';else if(n.type==='led')rows='<div class="pin-row component-pin-row"><button class="pin input" data-pin="0" aria-label="LED anode, positive"></button><span>ANODE <small>+</small></span><span class="output-state">OFF</span></div><div class="pin-row component-pin-row"><button class="pin input" data-pin="1" aria-label="LED cathode, negative"></button><span>CATHODE <small>−</small></span><span></span></div>';else if(n.type==='motor')rows='<div class="pin-row component-pin-row"><button class="pin input" data-pin="0" aria-label="Motor terminal M plus"></button><span>M+ <small>MOTOR</small></span><span class="output-state">STOPPED</span></div><div class="pin-row component-pin-row"><button class="pin input" data-pin="1" aria-label="Motor terminal M minus"></button><span>M− <small>MOTOR</small></span><span></span></div>';else rows='<div class="pin-row"><button class="pin input" data-pin="in" aria-label="Connect signal input"></button><span>SIGNAL IN</span><span class="output-state">—</span></div>';return `<div class="node-body">${body}</div>${rows}`}

function view(){world.style.transform=`translate(${pan.x}px,${pan.y}px) scale(${zoom})`;viewport.style.backgroundSize=`${20*zoom}px ${20*zoom}px`;viewport.style.backgroundPosition=`${pan.x}px ${pan.y}px`;$('#resetView').textContent=`${Math.round(zoom*100)}%`}
function setRestoreControls(){
 for(const selector of ['#start','#openDev','#run','#projectName','#componentLibrary']){
  $(selector).inert=!!pendingRestore;
 }
}
function render(){
 setRestoreControls();
 window.Wiring?.cancel();
 $('#projectName').value=state.name;$('#empty').hidden=!!state.nodes.length;
 $('#nodes').innerHTML=state.nodes.map(n=>n.type==='esp8266'?espHTML(n):n.type==='board'?boardHTML(n):`<div class="node ${n.type} ${n.id===selected?'selected':''}" data-id="${n.id}" style="left:${n.x}px;top:${n.y}px"><div class="node-header">${esc(componentLabel(n))}<span class="node-label">${state.nodes.filter(k=>k.type===n.type).indexOf(n)+1}</span></div>${n.type==='mcu'?`<div class="node-body">VIRTUAL CONTROLLER</div>${n.modes.map((m,p)=>`<div class="pin-row"><span>D${p}</span><span class="pin-state" data-pin="${p}">LOW</span><button class="pin ${pending?.id===n.id&&Number(pending.pin)===p?'pending':''}" data-pin="${p}" aria-label="Connect output D${p}"></button></div>`).join('')}`:peripheralHTML(n)}</div>`).join('');
 $('#counts').textContent=`${state.nodes.length} components · ${state.wires.length} connections`;view();drawWires();inspector();updateSignals();window.renderBoardLibrary?.();window.Firmware?.sync();save();
}
function pinElement(id,pin){const n=state.nodes.find(n=>n.id===id);if(!n)return null;return document.querySelector(`[data-id="${id}"] button[data-pin="${pin}"]`)}
function wireCurve(a,b){const bend=Math.max(35,Math.min(110,Math.abs(b.x-a.x)*.45));return `M${a.x} ${a.y} C${a.x+bend} ${a.y},${b.x-bend} ${b.y},${b.x} ${b.y}`}
function pinPoint(el){const origin=world.getBoundingClientRect(),r=el.getBoundingClientRect();return {x:(r.left+r.width/2-origin.left)/zoom,y:(r.top+r.height/2-origin.top)/zoom}}
function drawWires(){const svg=$('#wires');svg.innerHTML='';for(const w of state.wires){const ap=pinElement(w.from,w.pin),bp=pinElement(w.to,w.toPin??0);if(!ap||!bp)continue;const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',wireCurve(pinPoint(ap),pinPoint(bp)));path.setAttribute('class','wire');path.dataset.target=RobotModel.targetKey(w);const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent='Click to remove this connection';path.append(title);path.addEventListener('click',e=>{e.stopPropagation();snapshot();state.wires=state.wires.filter(k=>k!==w);render();toast('Connection removed. Undo to restore.')});svg.append(path)}}

function updateSignals(){for(const n of state.nodes){const el=document.querySelector(`[data-id="${n.id}"]`);if(!el)continue;if(isController(n)){el.querySelectorAll('.pin-state').forEach(p=>p.textContent=(RobotModel.kind(state,n,p.dataset.pin)==='input'?input(n,+p.dataset.pin):signal(n,+p.dataset.pin))?'HIGH':'LOW');el.querySelectorAll('.pin').forEach(p=>p.classList.toggle('high',RobotModel.kind(state,n,p.dataset.pin)==='input'?input(n,+p.dataset.pin):signal(n,+p.dataset.pin)))}else if(n.type==='battery'){el.querySelectorAll('.pin').forEach(p=>p.classList.toggle('high',signal(n,+p.dataset.pin)))}else if(ComponentRegistry.get(n.type)?.renderer==='generic'){el.querySelectorAll('.pin').forEach(p=>{const i=+p.dataset.pin,kind=RobotModel.kind(state,n,i);p.classList.toggle('high',kind==='output'?signal(n,i):kind==='power'?true:input(n,i))})}else if(n.type==='motorDriver'||n.type==='ultrasonic'){/* Physical pinout only; electrical behavior is not simulated. */}else{const hasPin=p=>state.wires.some(w=>w.to===n.id&&(w.toPin??0)===p);let high=false,label='';if(n.type==='servo'){high=input(n,0);label=high?'180°':'0°'}else if(n.type==='led'){high=input(n,0)&&hasPin(1);label=high?'ON':'OFF';el.querySelector('.pin[data-pin="1"]')?.classList.toggle('high',hasPin(1))}else if(n.type==='motor'){const a=input(n,0),b=input(n,1);high=hasPin(0)&&hasPin(1)&&a!==b;label=high?(a?'FORWARD':'REVERSE'):'STOPPED';el.querySelector('.pin[data-pin="1"]')?.classList.toggle('high',b)}el.querySelector('.pin[data-pin="0"],.pin[data-pin="in"]')?.classList.toggle('high',n.type==='motor'?input(n,0):high);el.querySelector('.output-state').textContent=label;el.querySelector('.light,.rotor')?.classList.toggle('on',high);if(n.type==='motor')el.querySelector('.rotor').style.animationPlayState=running?'running':'paused';if(n.type==='servo')el.querySelector('.arm').style.transform=`rotate(${high?180:0}deg)`}}document.querySelectorAll('.wire').forEach(p=>{const w=state.wires.find(w=>RobotModel.targetKey(w)===p.dataset.target);p.classList.toggle('high',signal(state.nodes.find(n=>n.id===w?.from),w?.pin));p.style.animationPlayState=running?'running':'paused'});document.querySelectorAll('[data-board-reading]').forEach(el=>{const n=state.nodes.find(n=>n.id===selected);if(n)el.textContent=input(n,+el.dataset.boardReading)?'HIGH':'LOW'});const n=state.nodes.find(n=>n.id===selected);if(n&&!isController(n)&&$('#reading'))$('#reading').textContent=!started?'Simulation stopped':n.type==='servo'?`Position: ${input(n,0)?180:0}°`:n.type==='led'?((input(n,0)&&state.wires.some(w=>w.to===n.id&&(w.toPin??0)===1))?'LED on (signal high; cathode grounded)':'LED off (needs signal and ground)'):n.type==='motor'?(!state.wires.some(w=>w.to===n.id&&(w.toPin??0)===0)||!state.wires.some(w=>w.to===n.id&&(w.toPin??0)===1)?'Connect both motor terminals':input(n,0)===input(n,1)?'Motor stopped (both terminals at same logic level)':`Motor ${input(n,0)?'forward':'reverse'} (logic model)`):n.type==='ultrasonic'?'Distance and echo timing are not simulated':n.type==='motorDriver'?'Driver switching and motor current are not simulated':'Power source';
}
function genericInspector(n){const def=ComponentRegistry.get(n.type),sources=[...(Array.isArray(def?.sources)?def.sources:[]),...(def?.source?[def.source]:[]),...(def?.visual?.imageSource?[{label:'Component image source',url:def.visual.imageSource}]:[])];$('#inspectorContent').innerHTML=`<h2 class="inspect-name">${esc(def?.name||n.type)}</h2><div class="inspect-type">${esc(def?.category||'Component')}</div><p class="inspect-help">${esc(def?.help||'Component pin map. Review the part documentation before wiring real hardware.')}</p><div class="generic-inspector-pins"><strong>TERMINALS</strong>${RobotModel.pins(state,n).map(p=>`<div>${esc(p.name)} <small>${esc(p.kind)}</small></div>`).join('')}</div>${sources.filter(s=>s&&/^https:\/\//.test(s.url||'')).map(s=>`<p class="inspect-help"><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label||s.title||'Part reference')}</a></p>`).join('')}${state.wires.some(w=>w.to===n.id||w.from===n.id)?'<button class="remove-wire" id="disconnect">Disconnect inputs</button>':''}<button class="remove-wire" id="removeSelected">Remove component</button>`;if($('#disconnect'))$('#disconnect').onclick=()=>{snapshot();state.wires=state.wires.filter(w=>w.to!==n.id&&w.from!==n.id);render()};$('#removeSelected').onclick=removeSelected}
function inspector(){const n=state.nodes.find(n=>n.id===selected);if(n&&RobotModel.firmwareTarget(state,n)){firmwareInspector(n);return}if(n?.type==='board'){boardInspector(n);return}if(n&&ComponentRegistry.get(n.type)?.renderer==='generic'){genericInspector(n);return}$('#inspectorContent').innerHTML=n?`<h2 class="inspect-name">${esc(componentLabel(n))}</h2><div class="inspect-type">${n.type==='mcu'?'Virtual digital controller':'Output component'}</div>${n.type==='mcu'?`<label class="field-label">OUTPUT BEHAVIOR</label>${n.modes.map((m,p)=>`<label class="signal-row">D${p}<select data-mode="${p}" aria-label="D${p} behavior"><option value="low" ${m==='low'?'selected':''}>Low</option><option value="high" ${m==='high'?'selected':''}>High</option><option value="blink" ${m==='blink'?'selected':''}>Pulse</option></select></label>`).join('')}<label class="field-label" for="period">Pulse cycle: <span id="periodText">${n.period.toFixed(1)}</span>s</label><input class="range" id="period" type="range" min="0.2" max="5" step="0.1" value="${n.period}"><p class="inspect-help">Drag a D0–D3 pin to an output component's signal pin. Set a pin to High or Pulse and run the simulation.</p>`:`<div class="reading" id="reading"></div><p class="inspect-help">${n.type==='ultrasonic'?'HC-SR04 module: four header pins VCC (5 V), TRIG, ECHO, GND. Send a trigger pulse to TRIG; the module returns an echo pulse on ECHO whose duration represents distance. Echo can reach 5 V, so protect 3.3 V NodeMCU inputs with a level shifter or resistor divider. Common ground is required. This canvas shows the pinout only; it does not measure distance or generate echo timing. <a href="https://cdn.sparkfun.com/datasheets/Sensors/Proximity/HCSR04.pdf?file=HCSR04.pdf" target="_blank" rel="noopener">HC-SR04 reference sheet</a>.':n.type==='motorDriver'?'SparkFun dual TB6612FNG breakout: 16 header connections, two H-bridge channels. VM is motor supply (2.5–13.5 V operating), VCC is logic supply (2.7–5.5 V), and GND pins are shared. PWMA/AIN1/AIN2 and PWMB/BIN1/BIN2 control channel speed/direction; STBY must be HIGH. Connect AO1/AO2 or BO1/BO2 across each motor. Up to 1.2 A continuous per channel (board/thermal conditions matter). Tie controller, logic supply, and motor supply grounds together. This canvas maps pins only; it does not calculate drive outputs, current, heat, or PWM. <a href="https://learn.sparkfun.com/tutorials/tb6612fng-hookup-guide/board-overview" target="_blank" rel="noopener">SparkFun hookup guide</a>.':n.type==='servo'?'TowerPro SG90 analog servo · 9 g · rated 4.8 V · 1.8 kg·cm stall torque · 0.12 s/60° at 4.8 V. Wire orange SIGNAL to a PWM-capable control pin, red V+ to a regulated 4.8 V supply, and brown/black GND to ground; join supply ground to controller ground. A servo uses timed control pulses (PWM); this canvas only maps Low/High to 0°/180°, so it does not model pulse width or servo power. <a href="https://towerpro.com.tw/product/sg90-analog/" target="_blank" rel="noopener">TowerPro specifications</a>.':n.type==='battery'?`${batteryInfo(n).description} Connect V+ and GND only to a load with a matching voltage rating. This canvas does not simulate voltage under load, charging, or current.`:n.type==='motor'?'Example: Pololu #1101 100:1 Micro Metal Gearmotor HP, 6 V; 310 rpm no-load, 100 mA no-load, about 1.6 A stall current. It has two motor terminals M+ and M−. Use a motor driver/H-bridge and a suitable 6 V supply; never power it directly from a NodeMCU GPIO. The canvas models forward/reverse from opposite logic levels only, not motor current or driver behavior. <a href="https://www.pololu.com/product/1101/" target="_blank" rel="noopener">Pololu specifications</a>.':n.type==='led'?'Example: Kingbright WP7113ID 5 mm red LED. Its two legs are ANODE (+) and CATHODE (−); observe polarity and add a series current-limiting resistor. For a 3.3 V GPIO and about 10 mA, 220 Ω is a common starting value. The animation checks signal and ground but does not calculate LED current. <a href="https://www.kingbrightusa.com/images/catalog/SPEC/wp7113id.pdf" target="_blank" rel="noopener">Kingbright datasheet</a>.':''}</p>${state.wires.some(w=>w.to===n.id||w.from===n.id)?'<button class="remove-wire" id="disconnect">Disconnect input</button>':`<p class="inspect-help">${n.type==='battery'?'Connect V+ and GND to matching power pins.':n.type==='led'?'Connect ANODE to a current-limited output and CATHODE to GND.':n.type==='motor'?'Connect both motor terminals to one driver channel output pair.':n.type==='motorDriver'?'Wire VM, VCC, GND, controller signals, then connect each motor across its output pair.':n.type==='ultrasonic'?'Wire 5 V and GND, TRIG to a controller output, and ECHO to a protected controller input.':'Connect the signal, supply, and ground terminals.'}</p>`}`}<button class="remove-wire" id="removeSelected">Remove component</button>`:'<div class="inspect-empty"><span class="inspect-icon">⌗</span><strong>Nothing selected</strong><p>Select a component on the canvas to see its properties.</p></div>';
 if(!n)return;document.querySelectorAll('[data-mode]').forEach(s=>s.onchange=()=>{snapshot();n.modes[+s.dataset.mode]=s.value;save();updateSignals()});if($('#period')){$('#period').onpointerdown=()=>snapshot();$('#period').onkeydown=e=>{if(e.key.startsWith('Arrow'))snapshot()};$('#period').oninput=e=>{n.period=+e.target.value;$('#periodText').textContent=n.period.toFixed(1);save()}}if($('#disconnect'))$('#disconnect').onclick=()=>{snapshot();state.wires=state.wires.filter(w=>w.to!==n.id&&w.from!==n.id);render()};$('#removeSelected').onclick=removeSelected;
}
function add(type,pack){if(type==='esp8266')return addEsp8266();const definition=ComponentRegistry.get(type);if(!definition)return toast('This component is not in the catalog yet.');if(state.nodes.length>=150)return toast('This workspace supports up to 150 components.');snapshot();const rect=viewport.getBoundingClientRect();const offset=(state.nodes.length%5)*24;const n={id:uid(),type,...(definition.variants?.length?{pack:pack||definition.variants[0].id}:{}),x:Math.round(((rect.width/2-84-pan.x)/zoom+offset)/10)*10,y:Math.round(((rect.height/2-100-pan.y)/zoom+offset)/10)*10,modes:definition.renderer==='generic'?definition.pins.map(()=> 'low'):['blink','low','low','low'],period:1};state.nodes.push(n);selected=n.id;render();toast(`${catalogLabel(type)} added`)}
function buildComponentLibrary(){const host=$('#componentLibrary');if(!host)return;const definitions=ComponentRegistry.catalog(),groups=new Map();for(const def of definitions){if(!def.category||def.renderer==='board')continue;if(!groups.has(def.category))groups.set(def.category,[]);const variants=def.variants?.length?def.variants:[null];for(const variant of variants)groups.get(def.category).push({def,variant})}host.innerHTML=[...groups].map(([category,items])=>`<div class="category">${esc(category)}</div>${items.map(({def,variant})=>`<button class="part" data-type="${esc(def.id)}" ${variant?`data-pack="${esc(variant.id)}"`:''}><span class="part-art ${esc(def.iconClass||'chip')}">${esc(def.icon||'▦')}</span><span><strong>${esc(variant?.name||def.name)}</strong><small>${esc(variant?.subtitle||def.subtitle||'')}</small></span><span class="add">+</span></button>`).join('')}`).join('');$('#libraryCount').textContent=String([...groups.values()].reduce((sum,items)=>sum+items.length,0))}
function initializeComponentLibrary(){document.querySelectorAll('.library > .category,.library > .part').forEach(el=>el.remove());const host=document.createElement('div');host.id='componentLibrary';$('#noResults').before(host);buildComponentLibrary()}
function removeSelected(){if(!selected)return toast('Select a component first.');snapshot();state.nodes=state.nodes.filter(n=>n.id!==selected);state.wires=state.wires.filter(w=>w.from!==selected&&w.to!==selected);selected=null;pending=null;render()}
function commitConnection(from,to){const wire=RobotModel.connection(state,from,to);if(!wire){toast('Connect an output, power, or ground pin to an input on another component.');return false}const existing=state.wires.find(w=>RobotModel.targetKey(w)===RobotModel.targetKey(wire));if(existing?.from===wire.from&&existing.pin===wire.pin){pending=null;render();return true}if(!existing&&state.wires.length>=600){toast('Maximum 600 connections per project.');return false}snapshot();state.wires=state.wires.filter(w=>RobotModel.targetKey(w)!==RobotModel.targetKey(wire));state.wires.push(wire);pending=null;render();toast(existing?'Input reconnected. Undo restores its previous connection.':'Pins connected');return true}
function connect(id,pin){if(!pending){pending={id,pin};render();window.Wiring?.highlight(pending);toast('Drag to another pin, or click a compatible pin to connect.');return}if(pending.id===id&&String(pending.pin)===String(pin)){pending=null;render();return}commitConnection(pending,{id,pin})}

let drag=null;
viewport.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button,.wire,#empty,.zoom,.floating-tools'))return;const el=e.target.closest('.node');if(el){selected=el.dataset.id;document.querySelectorAll('.node').forEach(x=>x.classList.toggle('selected',x===el));inspector();updateSignals();const n=state.nodes.find(n=>n.id===selected);drag={kind:'node',id:n.id,sx:e.clientX,sy:e.clientY,x:n.x,y:n.y,moved:false}}else{selected=null;pending=null;render();drag={kind:'pan',sx:e.clientX,sy:e.clientY,x:pan.x,y:pan.y}}viewport.setPointerCapture(e.pointerId)});
viewport.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.sx,dy=e.clientY-drag.sy;if(drag.kind==='pan'){pan={x:drag.x+dx,y:drag.y+dy};view()}else{if(!drag.moved&&(Math.abs(dx)+Math.abs(dy)>3)){snapshot();drag.moved=true}if(drag.moved){const n=state.nodes.find(n=>n.id===drag.id);n.x=Math.round((drag.x+dx/zoom)/10)*10;n.y=Math.round((drag.y+dy/zoom)/10)*10;const el=document.querySelector(`[data-id="${n.id}"]`);el.style.left=n.x+'px';el.style.top=n.y+'px';drawWires();updateSignals()}}});
for(const event of ['pointerup','pointercancel'])viewport.addEventListener(event,()=>{if(drag?.kind==='node')save();drag=null});

function setZoom(z,cx=viewport.clientWidth/2,cy=viewport.clientHeight/2){const next=Math.max(.3,Math.min(2,z));pan.x=cx-(cx-pan.x)*next/zoom;pan.y=cy-(cy-pan.y)*next/zoom;zoom=next;view()}
viewport.addEventListener('wheel',e=>{e.preventDefault();const r=viewport.getBoundingClientRect();setZoom(zoom*(e.deltaY>0?.9:1.1),e.clientX-r.left,e.clientY-r.top)},{passive:false});
$('#zoomIn').onclick=()=>setZoom(zoom+.1);$('#zoomOut').onclick=()=>setZoom(zoom-.1);$('#resetView').onclick=()=>{zoom=1;if(state.nodes.length){const xs=state.nodes.map(n=>n.x),ys=state.nodes.map(n=>n.y);pan={x:viewport.clientWidth/2-(Math.min(...xs)+Math.max(...xs)+168)/2,y:viewport.clientHeight/2-(Math.min(...ys)+Math.max(...ys)+200)/2}}else pan={x:0,y:0};view()};
initializeComponentLibrary();$('#componentLibrary').onclick=e=>{const b=e.target.closest('.part[data-type]');if(b)add(b.dataset.type,b.dataset.pack)};$('#start').onclick=()=>add('mcu');$('#delete').onclick=removeSelected;
function undo(){if(!history.length)return toast('Nothing to undo yet.');state=JSON.parse(history.pop());selected=null;pending=null;render();toast('Change undone')};$('#undo').onclick=undo;
$('#selectTool').onclick=()=>{pending=null;viewport.classList.remove('wiring');$('#selectTool').classList.add('active');$('#wireTool').classList.remove('active');render()};$('#wireTool').onclick=()=>{viewport.classList.add('wiring');$('#wireTool').classList.add('active');$('#selectTool').classList.remove('active');toast('Drag from a pin to a highlighted compatible pin. You can also click two pins.')};
$('#run').onclick=()=>{if(!state.nodes.some(isController))return toast('Add a microcontroller to start simulating.');running=!running;started=true;last=0;window.Firmware?.sync();$('#run').innerHTML=running?'Ⅱ <span>Pause simulation</span>':'▶ <span>Run simulation</span>';$('#simLabel').textContent=running?'Simulation running':'Simulation paused';$('#status').textContent=running?'Simulating digital signals':'Simulation paused';updateSignals()};
function tick(t){if(running&&last)elapsed+=Math.min(t-last,100);last=t;if(running){window.Firmware?.sendInputs();updateSignals()}window.Firmware?.refreshPanel();requestAnimationFrame(tick)}requestAnimationFrame(tick);
$('#search').oninput=e=>{let count=0;document.querySelectorAll('.part').forEach(b=>{b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!b.hidden)count++});$('#noResults').hidden=!!count};
$('#projectName').onchange=e=>{snapshot();state.name=e.target.value.trim()||'Untitled project';render()};
$('#clear').onclick=()=>{if(!state.nodes.length)return toast('Your canvas is already blank.');snapshot();state.nodes=[];state.wires=[];selected=null;pending=null;running=false;started=false;elapsed=0;$('#run').innerHTML='▶ <span>Run simulation</span>';$('#simLabel').textContent='Simulation stopped';$('#status').textContent='Ready when you are';render();toast('Canvas cleared. Use Undo to restore.')};
$('#exportBtn').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(pendingRestore||state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=(state.name.replace(/[^a-z0-9_-]/gi,'-')||'robot-canvas')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Project exported')};
$('#importBtn').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>8000000)throw Error('File is too large. Maximum: 8 MB.');const s=migrateProject(JSON.parse(await f.text()));if(!valid(s))throw Error('Choose a valid Robot Canvas project JSON file.');snapshot();pendingRestore=null;state=s;state.boards??=[];selected=null;pending=null;render();$('#resetView').click();toast('Project imported. Undo restores your previous canvas.')}catch(err){toast(err instanceof SyntaxError?'This file is not valid JSON.':err.message)}e.target.value=''};
document.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea,dialog'))return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removeSelected()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo()}if(e.key==='Escape'){window.Wiring?.cancel();pending=null;selected=null;render()}});
render();

window.addEventListener('resize',drawWires);document.fonts?.ready.then(drawWires);

// Keep every workspace control behind one button; canvas coordinates stay fixed.
$('#toggleUI').onclick=()=>{
 const hidden=document.body.classList.toggle('ui-hidden');
 $('#toggleUI').setAttribute('aria-expanded',String(!hidden));
 $('#toggleUI').textContent=hidden?'☰ Controls':'× Hide controls';
 if(hidden){pending=null;render()}
};

window.refreshComponentRegistry=definitions=>{
 ComponentRegistry.replace(definitions);
 buildComponentLibrary();
 $('#noResults').textContent='No components found.';
 $('#search').oninput({target:$('#search')});
 if(pendingRestore){
  if(!valid(migrateProject(pendingRestore))){
   $('#saved').textContent='Saved project needs unavailable parts';
   return;
  }
  state=pendingRestore;
  state.boards??=[];
  pendingRestore=null;
 }
 render();
};
window.CanvasAI={
 current(){return state.nodes.map((n,index)=>({index,id:n.id,type:n.type,label:componentLabel(n),pins:RobotModel.pins(state,n).map((p,pin)=>({pin,name:p.name,kind:p.kind}))}))},
 apply(plan){
  if(pendingRestore)throw Error('Wait for the component catalog to restore your saved project.');
  if(!plan||!Array.isArray(plan.components)||!Array.isArray(plan.wires)||plan.components.length>20||plan.wires.length>60)throw Error('The proposed build is too large. Try a smaller idea.');
  if(state.nodes.length+plan.components.length>150)throw Error('The canvas limit is 150 components. Remove a few parts first.');
  if(plan.components.some(c=>{const def=ComponentRegistry.get(c?.type);return !def||(def.variants?.length&&!def.variants.some(v=>v.id===c.pack))}))throw Error('The plan included a part that is not in this canvas library.');
  if(plan.components.filter(c=>c.type==='esp8266').length+state.nodes.filter(n=>RobotModel.firmwareTarget(state,n)).length>4)throw Error('This workspace supports up to four firmware boards per project.');
  const rect=viewport.getBoundingClientRect(),startX=(rect.width/2-pan.x)/zoom-180,startY=(rect.height/2-pan.y)/zoom-100;
  const additions=plan.components.map((c,i)=>{const def=ComponentRegistry.get(c.type);return {id:uid(),type:c.type,...(def.variants?.length?{pack:c.pack}:{}),x:Math.round((startX+(i%3)*210)/10)*10,y:Math.round((startY+Math.floor(i/3)*180)/10)*10,modes:c.type==='esp8266'?RobotModel.espPins.map(()=> 'low'):def.renderer==='generic'?def.pins.map(()=> 'low'):['blink','low','low','low'],period:1,...(c.type==='esp8266'?{firmware:{preset:'blink'}}:{})}});
  const combined=[...state.nodes,...additions],newWires=[];
  for(const w of plan.wires){if(!w||![w.aComponent,w.aPin,w.bComponent,w.bPin].every(Number.isInteger)||w.aComponent<0||w.bComponent<0||w.aComponent>=combined.length||w.bComponent>=combined.length)throw Error('The plan referred to a component or pin that does not exist.');const wire=RobotModel.connection({ ...state,nodes:combined },{id:combined[w.aComponent].id,pin:w.aPin},{id:combined[w.bComponent].id,pin:w.bPin});if(!wire)throw Error(`The suggested connection between ${componentLabel(combined[w.aComponent])} and ${componentLabel(combined[w.bComponent])} is not compatible with their pin types.`);if(state.wires.some(existing=>RobotModel.targetKey(existing)===RobotModel.targetKey(wire))||newWires.some(existing=>RobotModel.targetKey(existing)===RobotModel.targetKey(wire)))continue;newWires.push(wire)}
  if(state.wires.length+newWires.length>600)throw Error('The canvas limit is 600 connections per project.');
  const next={...state,nodes:combined,wires:[...state.wires,...newWires]};if(!RobotModel.valid(next))throw Error('The proposed build did not pass the canvas checks. Try describing a simpler circuit.');
  if(additions.length||newWires.length){snapshot();state=next;selected=additions.at(-1)?.id||selected;pending=null;render()}
  return {added:additions.length,connected:newWires.length};
 }
};

function boardInspector(n){const b=boardFor(n);$('#inspectorContent').innerHTML=`<h2 class="inspect-name">${esc(b.name)}</h2><div class="inspect-type">Custom digital board · ${b.pins.length} pins</div>${b.pins.map((p,i)=>`<div class="signal-row"><label for="customMode${i}">${esc(p.name)}<small class="pin-kind">${p.kind}</small></label>${p.kind==='output'?`<select id="customMode${i}" data-mode="${i}" aria-label="${esc(p.name)} behavior">${['low','high','blink'].map(m=>`<option value="${m}" ${n.modes[i]===m?'selected':''}>${m==='blink'?'Pulse':m==='high'?'High':'Low'}</option>`).join('')}</select>`:p.kind==='input'?`<span data-board-reading="${i}">LOW</span>`:`<span>${p.kind==='power'?'HIGH':'LOW'}</span>`}</div>`).join('')}<label class="field-label" for="period">Pulse cycle: <span id="periodText">${n.period.toFixed(1)}</span>s</label><input class="range" id="period" type="range" min="0.2" max="5" step="0.1" value="${n.period}"><p class="inspect-help">Marked pins carry digital signals. Inputs show their received state; power and ground provide fixed High and Low. Firmware and electrical behavior are not emulated.</p><button class="remove-wire" id="editThisBoard">Edit board pins</button><button class="remove-wire" id="disconnectBoard">Disconnect all</button><button class="remove-wire" id="removeSelected">Remove component</button>`;
 document.querySelectorAll('[data-mode]').forEach(s=>s.onchange=()=>{snapshot();n.modes[+s.dataset.mode]=s.value;save();updateSignals()});$('#period').onpointerdown=()=>snapshot();$('#period').onkeydown=e=>{if(e.key.startsWith('Arrow'))snapshot()};$('#period').oninput=e=>{n.period=+e.target.value;$('#periodText').textContent=n.period.toFixed(1);save()};$('#editThisBoard').onclick=()=>window.openBoardEditor(b.id);$('#disconnectBoard').onclick=()=>{snapshot();state.wires=state.wires.filter(w=>w.from!==n.id&&w.to!==n.id);render()};$('#removeSelected').onclick=removeSelected;
}
function addBoard(id){const b=state.boards.find(b=>b.id===id);if(!b)return;if(b.runtime==='esp8266'&&state.nodes.filter(n=>RobotModel.firmwareTarget(state,n)).length>=4)return toast('Up to four firmware boards can run per project.');if(state.nodes.length>=150)return toast('This workspace supports up to 150 components.');snapshot();const n={id:uid(),type:'board',boardId:id,x:(viewport.clientWidth/2-pan.x)/zoom-140,y:(viewport.clientHeight/2-pan.y)/zoom-100,modes:b.pins.map(()=> 'low'),period:1};if(b.runtime==='esp8266')n.firmware={preset:'blink'};state.nodes.push(n);selected=n.id;render();toast('Board added. Connect a pin and set its output in the inspector.')}

function espHTML(n){const pins=RobotModel.pins(state,n),side=name=>pins.map((p,i)=>({...p,index:i})).filter(p=>p.side===name).sort((a,b)=>a.position-b.position),silk=p=>p.name.split(' / ')[0].replace(' · ADC','');const pad=(p,sideName)=>`<div class="esp-pad ${sideName}" title="${p.note?esc(p.note):esc(p.name+(p.gpio!=null?' = GPIO'+p.gpio:''))}">${sideName==='left'?`<span class="esp-label">${esc(silk(p))}</span>`:`<button class="pin esp-pin ${p.kind==='input'?'input':''} ${p.kind==='reserved'?'reserved':''} ${pending?.id===n.id&&Number(pending.pin)===p.index?'pending':''}" data-pin="${p.index}" aria-label="${esc(p.name)}${p.gpio!=null?' GPIO '+p.gpio:''} · ${p.kind}" ${p.kind==='reserved'?'disabled aria-disabled="true"':''}></button>`}${sideName==='left'?`<button class="pin esp-pin ${p.kind==='input'?'input':''} ${p.kind==='reserved'?'reserved':''} ${pending?.id===n.id&&Number(pending.pin)===p.index?'pending':''}" data-pin="${p.index}" aria-label="${esc(p.name)} · ${p.kind}" ${p.kind==='reserved'?'disabled aria-disabled="true"':''}></button>`:`<span class="esp-label">${esc(silk(p))}</span>`}</div>`;return `<div class="node esp8266 ${n.id===selected?'selected':''}" data-id="${n.id}" style="left:${n.x}px;top:${n.y}px"><div class="node-header">NodeMCU DevKit v1.0<span class="node-label">ESP-12E</span></div><div class="esp-board"><span class="esp-hole hole-tl"></span><span class="esp-hole hole-tr"></span><span class="esp-hole hole-bl"></span><span class="esp-hole hole-br"></span><div class="esp-side left">${side('left').map(p=>pad(p,'left')).join('')}</div><div class="esp-core"><div class="esp-antenna" aria-hidden="true"></div><div class="esp-metal"><strong>WiFi</strong><small>ESP-12E · ESP8266</small></div><span class="esp-regulator">SPX3819</span><span class="esp-uart-chip">CP2102</span><span class="esp-led">●</span><span class="esp-control rst">RST</span><span class="esp-control flash">FLASH</span><span class="esp-usb" aria-label="Micro USB connector"></span></div><div class="esp-side right">${side('right').map(p=>pad(p,'right')).join('')}</div></div><div class="esp-caption">NodeMCU DevKit 1.0 · 30 header positions</div></div>`}
function addEsp8266(){if(state.nodes.length>=150)return toast('Maximum 150 components.');if(state.nodes.filter(n=>RobotModel.firmwareTarget(state,n)).length>=4)return toast('Up to four firmware boards can run per project.');snapshot();const n={id:uid(),type:'esp8266',x:(viewport.clientWidth/2-pan.x)/zoom-84,y:(viewport.clientHeight/2-pan.y)/zoom-150,modes:RobotModel.espPins.map(()=> 'low'),period:1,firmware:{preset:'blink'}};state.nodes.push(n);selected=n.id;render();toast('NodeMCU added. Run simulation to execute the Blink firmware on D4 / GPIO2.')}
